package com.example.starter.trajectory.dto;

/**
 * 二维平面点，坐标单位为米。
 *
 * @param x 纵向/东向坐标，单位米
 * @param y 横向/北向坐标，单位米
 */
public record Point(double x, double y) {
}

package com.example.starter.trajectory.dto;

/**
 * 带时间戳的二维点，用于轨迹点与障碍物预测点。
 *
 * @param t 时间戳，单位秒（相对同一时间原点）
 * @param x 坐标 x，单位米
 * @param y 坐标 y，单位米
 */
public record TimedPoint(double t, double x, double y) {

    /** 转换为不带时间的平面点。 */
    public Point toPoint() {
        return new Point(x, y);
    }
}

package com.example.starter.trajectory.dto;

/**
 * 车辆初始状态。
 *
 * @param x       初始位置 x，单位米
 * @param y       初始位置 y，单位米
 * @param heading 初始航向角，单位弧度
 * @param speed   初始速度，单位米每秒
 */
public record VehicleState(double x, double y, double heading, double speed) {
}

package com.example.starter.trajectory.dto;

import java.util.List;

/**
 * 单个障碍物带唯一 ID 的预测轨迹，点按时间严格递增。
 *
 * @param id     障碍物唯一 ID，碰撞失败项通过该 ID 关联对象
 * @param points 障碍物预测点列表，按时间升序
 */
public record ObstaclePrediction(String id, List<TimedPoint> points) {
}

package com.example.starter.trajectory.dto;

import java.util.List;

/**
 * 道路边界，按顺序排列的闭合多边形顶点（首尾无需重复）。
 * 多边形边上的轨迹点视为合法；点在外部且超出道路容差才判定失败。
 *
 * @param polygon 道路边界多边形顶点，单位米
 */
public record RoadBoundary(List<Point> polygon) {
}

