package com.example.starter.trajectory.exception;

/**
 * 请求与已存在资源状态冲突（如幂等键同键异参、规则版本重复发布），对应 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.trajectory.exception;

/**
 * 引用的资源（如规则版本）不存在，对应 HTTP 404。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.trajectory.exception;

/**
 * 请求载荷语义非法（如道路多边形不足三个顶点），对应 HTTP 400。
 */
public class BadRequestException extends RuntimeException {

    public BadRequestException(String message) {
        super(message);
    }
}

package com.example.starter.trajectory.engine;

import com.example.starter.trajectory.dto.FailureItem;
import com.example.starter.trajectory.dto.RuleConfig;
import com.example.starter.trajectory.dto.ValidationRequest;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * 轨迹安全规则引擎：时间连续性、动力学、道路、碰撞四组规则并行执行，
 * 输出按规则编号、首次触发时间、对象 ID 确定性排序。
 */
@Component
public class SafetyValidationEngine {

    /**
     * 执行全部安全规则。
     *
     * @param config  不可变规则阈值
     * @param request 轨迹校验请求
     * @return 确定性排序后的失败项（骨架阶段为空）
     */
    public List<FailureItem> validate(RuleConfig config, ValidationRequest request) {
        return List.of();
    }
}

