                if (xAtRay > p.x()) {
                    inside = !inside;
                }
            }
        }
        return inside;
    }

    /**
     * 三点 a、b、c 的外接圆曲率绝对值，κ = 4·面积 / (|ab|·|bc|·|ca|)；
     * 共线或存在重合点时曲率为 0。
     */
    static double curvature(Point a, Point b, Point c) {
