    rule_version      VARCHAR(64) NOT NULL,
    max_time_interval DOUBLE      NOT NULL,
    max_speed         DOUBLE      NOT NULL,
    max_acceleration  DOUBLE      NOT NULL,
    max_curvature     DOUBLE      NOT NULL,
