/** 边界判定容差，单位米。 */
static final double EPS = 1e-9;

/**
 * 严格超界判定，附带 1e-9 相对/绝对误差以吸收双精度舍入（如曲率 1/R），
 * 即值恰好等于阈值时仍判合法，只有明确超出才失败。
 */
private static boolean exceeds(double value, double limit) {
    return value > limit + Math.max(EPS, EPS * Math.abs(limit));
}

